void *ass_realloc_array(void *ptr, size_t nmemb, size_t size) /* <=== ass_realloc_array */ 
{
    if (nmemb > (SIZE_MAX / size))
        return NULL;
    size *= nmemb;
    if (size < 1)
        size = 1;

    return realloc(ptr, size);
}

